option.value:
/* Simplified ZX Spectrum 48K inspired CSS */
@font-face {
    font-family: 'pyrmont_brewery';
    src: url('pyrmont_brewery.woff2') format('woff2');
    font-display: swap;
}
:root {
    --zx-base-font-size: 18px;
    --zx-double-font-size: 36px;
}
html, body {
    font-family: 'pyrmont_brewery', 'DejaVu Sans Mono', monospace;
    font-size: var(--zx-base-font-size);
    background: #1a1a1a;
    color: #fff;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}
header, nav, main, footer, div, p, ul, ol, li, a, img, button, input, select, textarea {
    border-radius: 0 !important;
    border: none !important;
    background: none;
}
div, header, nav, main, footer {
    margin-bottom: 8px;
    padding: 8px 0;
}
p, ul, ol {
    width: 90%;
    margin: 0 auto 8px auto;
    background: #222;
    color: #fff;
    padding: 8px 18px;
}
ul, ol {
    list-style-position: inside;
    font-size: var(--zx-base-font-size);
}
ul { list-style-type: square; }
ol { list-style-type: decimal; }
li { padding: 2px 0; }
ul li::marker {
    font-size: var(--zx-double-font-size);
    color: #00ffff;
    font-weight: bold;
}
a {
    color: #ff0;
    background: #222;
    padding: 2px 4px;
    font-weight: bold;
    text-decoration: none;
    display: inline-block;
}
a:hover, a:focus {
    animation: zx-flash 1s steps(1, end) infinite;
    outline: 3px solid #0f0;
    color: #fff;
}
img {
    border: 5px solid #fff;
    background: #222;
    max-width: 100%;
    height: auto;
}
button, input, select, textarea {
    font-family: inherit;
    font-size: inherit;
    background: #222;
    color: #fff;
    border: 2px solid #fff;
    padding: 6px 12px;
    margin: 4px 0;
}
input[type="number"] {
    padding-right: 20px;
    text-align: right;
    -moz-appearance: textfield;
    position: relative;
}
input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
    opacity: 1;
    background: #00ff00;
}
::-webkit-scrollbar {
    width: 16px;
    background: #222;
}
::-webkit-scrollbar-thumb {
    background: #fff;
}
.visually-hidden, .skip-link {
    position: absolute;
    left: -10000px;
    width: 1px;
    height: 1px;
    overflow: hidden;
}
.skip-link:focus {
    left: 0; top: 0; width: auto; height: auto;
    background: #0f0; color: #000; z-index: 1000;
    padding: 8px; border: 4px solid #000;
}
.spectrum-border {
    border: 8px solid #ff0000;
    box-shadow: 0 0 0 8px #00ff00, 0 0 0 16px #0000ff;
}
h1, h2, h3, h4, h5, h6 {
    font-family: inherit;
    background: #222;
    padding: 8px;
    margin-bottom: 10px;
}
h1 { color: #00ff00; font-size: var(--zx-double-font-size); text-align: center; }
h2 { color: #ff00ff; font-size: var(--zx-double-font-size); border-bottom: 1px solid #333; }
h3 { color: #00ffff; font-size: var(--zx-base-font-size); }
h4, h5, h6 { color: #ffff00; font-size: var(--zx-base-font-size); }
.video-bg {
    position: fixed;
    top: 0; left: 0; width: 100vw; height: 100vh;
    z-index: -1; object-fit: cover; pointer-events: none;
}
@keyframes zx-flash {
    0%, 100% { background: #000; color: #fff; }
    50% { background: #0f0; color: #000; }
}
@media (prefers-color-scheme: dark) {
    html, body { background-color: #303030; }
}

